export const createWebhookBodyNameMax = 80;

export const createWebhookBodyUrlMin = 8;
export const createWebhookBodyUrlMax = 2000;



export const CreateWebhookBody = zod.object({
  "name": zod.string().min(createWebhookBodyNameMin).max(createWebhookBodyNameMax),
  "url": zod.string().min(createWebhookBodyUrlMin).max(createWebhookBodyUrlMax)
})

export const CreateWebhookResponse = zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "url": zod.string(),
  "status": zod.enum(['active']),
  "createdAt": zod.coerce.date()
})





export const DeleteWebhookParams = zod.object({
  "id": zod.coerce.string().min(1)
})

export const DeleteWebhookResponse = zod.void()


export const ListWebhookDeliveriesResponseItem = zod.object({
  "id": zod.string(),
  "webhookId": zod.string(),
  "event": zod.enum(['lead.created']),
  "status": zod.enum(['pending', 'delivered', 'failed']),
  "attemptCount": zod.number(),
  "httpStatus": zod.number().nullish(),
  "lastError": zod.string().nullish(),
  "deliveredAt": zod.string().nullish(),
  "createdAt": zod.coerce.date()
})
export const ListWebhookDeliveriesResponse = zod.array(ListWebhookDeliveriesResponseItem)


